async function openWorkingCopy(){try{return await loadWorkingCopy();}catch(error){document.querySelector('#main').textContent='Your saved records could not be opened. No records were replaced. Close other Relay tabs and reload. '+error.message;throw error;}}
let state=await openWorkingCopy(),wing='helm',directoryFilter='All',searchText='',expanded=false,planningOverride=null,goalYear=new Date().getFullYear(),tideFilter='Active';
