function supportMosaic(c){const off=givingInterruptions(state).find(r=>r.contact.id===c.id);const trait=(name,key,ic)=>`<section class="panel mini-panel">${icon(ic)}<h3>${name}</h3><p><span class="dot ${c[key]==='Available'?'green':c[key]==='Unavailable'?'pink':'unknown'}"></span>${e(c[key]||'Unknown')}</p></section>`;return `<div class="support-mosaic"><section class="panel support-tall"><div>${icon('support','gold')}<h3>Support</h3><span class="small gold">${e(c.supportStatus)}</span></div><div class="amount">${MONEY.format(c.supportAmount||0)}</div><span class="subtle small">${e(c.supportCadence||'Not set')}</span><div class="cadence">${icon('refresh')} ${off?`${off.missed} expected gifts missed`:'On cadence'}</div></section>${trait('Lodging','lodging','bed')}${trait('RV hookup','rv','rv')}${trait('Bible handouts','handouts','manifest')}</div>`;}
function givingHistory(c){const year=goalYear,records=state.gifts.filter(g=>g.contactId===c.id&&date(g.date).getFullYear()===year),total=records.reduce((n,g)=>n+Number(g.amount),0);return `<section class="panel gift-history">${section('Giving history')}<div class="row between"><span class="subtle small">${year} received</span><span style="font:400 33px var(--serif)">${MONEY.format(total)}</span></div><div class="gift-dots">${Array.from({length:12},(_,m)=>`<div class="gift-dot">${new Date(year,m,1).toLocaleDateString('en-US',{month:'short'}).toUpperCase()}<i class="${records.some(g=>date(g.date).getMonth()===m)?'paid':''}"></i></div>`).join('')}</div>${btn('gift-form','Record gift','plain-btn wide',`data-id="${e(c.id)}"`)}</section>`;}
function personalizedMessage(c,template){const last=String(c.pastor||'').trim().split(/\s+/).pop()||'Friend';return String(template||'').replaceAll('[Last name]',last).replaceAll('[Name]',c.pastor||last).replaceAll('[Title]',isFriend(c)?'':`Pastor ${last}`);}
function renderRelayList(){const w=relayWeek(),list=state.contacts.filter(c=>c.wing==='manifest'&&c.relayGroup===w.group&&callable(c,state.settings.showNoNumbers)&&!relayCompleted(c,state.logs)),template=state.settings.weeklyRelayMessage||'Good morning, [Title],\n\nI hope you had a good weekend. I wanted to check in and let you know that I appreciate you, your family, and your ministry.';return `${topbar('This week’s Relay')}<div class="page"><h1 class="month-title">${w.group?`Group ${w.group}`:'A week at harbor'}</h1><p class="subtle small">${short(w.start)}–${short(w.end)} · Any attempted contact counts.</p><form id="weekly-message" class="panel form weekly-message"><h3>This week’s message</h3><p class="small subtle">Edit once for this week. [Title], [Name], and [Last name] personalize each preview. Nothing sends automatically.</p><textarea name="message" required>${e(template)}</textarea><button class="secondary wide" type="submit">Save weekly message</button></form>${list.map(c=>{const message=personalizedMessage(c,template),p=phones(c)[0];return `<article class="panel relay-message"><h3>${e(c.pastor)}</h3><p>${e(message)}</p>${p?`<a class="primary wide" href="sms:${e(p.replace(/[^+\d]/g,''))}?&body=${encodeURIComponent(message)}">${icon('text')}Review in Messages</a>`:''}</article>`}).join('')||empty(w.group?'All ships accounted for':'A week at harbor',w.group?'This group’s Relays are complete.':'The fifth week is your break week.')}</div>`;}
function renderTides(){let list=state.tides.filter(t=>tideFilter==='Completed'?t.completed&&t.completedAt>=iso(addDays(new Date(),-30)):!t.completed&&!t.legacyHidden);if(searchText)list=state.tides.filter(t=>(tideFilter==='Completed'?t.completed:!t.completed&&!t.legacyHidden)&&`${t.title} ${contact(t.contactId)?.pastor} ${t.note}`.toLowerCase().includes(searchText.toLowerCase()));return `${hero('tides','Keep every intention within reach.')}<div class="page">${searchUI('Search Tides and relationships…')}<div class="row between"><div class="chips">${['Active','Completed'].map(f=>btn('tide-filter',f,`chip ${tideFilter===f?'active':''}`,`data-filter="${f}"`)).join('')}</div>${btn('tide-form',`${icon('plus')}Tide`,'outlined')}</div>${(tideFilter==='Completed'?['Completed']:['Overdue','Today','This Week','Later']).map(group=>{const items=list.filter(t=>tideGroup(t)===group).sort((a,b)=>a.due.localeCompare(b.due));if(group==='Later')return [...new Set(items.map(t=>t.due.slice(0,4)))].map(year=>`<h2 class="tide-year">${e(year)}</h2>${[...new Set(items.filter(t=>t.due.startsWith(year)).map(t=>t.due.slice(0,7)))].map(month=>`${section(date(month+'-01').toLocaleDateString('en-US',{month:'long'}))}${items.filter(t=>t.due.startsWith(month)).map(tideItem).join('')}`).join('')}`).join('');return items.length?`${section(group)}${items.map(tideItem).join('')}`:'';}).join('')||empty('Still waters','All your Tides are cleared.')}${tideFilter==='Completed'?'<p class="tiny subtle">Last 30 days. Search to find any completed Tide.</p>':''}</div>`;}
function tideItem(t){const c=contact(t.contactId),group=tideGroup(t);return `<article class="tide-row ${group==='Overdue'?'overdue':''}"><button class="tide-row-main" data-action="tide-card" data-id="${e(t.id)}">${c?avatar(c):'<span class="medallion">'+icon(t.action)+'</span>'}<span class="tide-row-copy"><strong>${e(c?.pastor||'Unlinked Tide')}</strong><span class="tide-church">${e([c?.church,c?locationLabel(c):''].filter(Boolean).join(' · '))}</span><span class="tide-context">${e(tideContext(t))}</span><span class="tide-date">${e(group==='Overdue'?'Overdue · ':'')}${e(short(t.due))}${t.due?.slice(0,4)!==String(new Date().getFullYear())?', '+e(t.due.slice(0,4)):''}${t.time?' · '+e(t.time):''}</span></span></button><div class="tide-row-actions">${c?btn('open-contact',icon('person'),'icon-btn',`data-id="${e(c.id)}" aria-label="Open contact for ${e(c.pastor)}"`):''}${!t.completed&&!t.legacyHidden?btn('complete-tide',icon('check'),'icon-btn',`data-id="${e(t.id)}" aria-label="Complete Tide for ${e(c?.pastor||'this reminder')}"`):''}</div></article>`;}
function tideCard(id){const t=state.tides.find(t=>t.id===id);if(!t)return;const c=contact(t.contactId);openSheet('Tide',`<div class="tide-card-body"><div class="row between"><span class="badge tide">${e(tideGroup(t))}</span>${btn('tide-form','Edit','outlined',`data-tide="${e(t.id)}"`)}</div><h3>${e(c?.pastor||'Unlinked Tide')}</h3><p class="subtle">${e([c?.church,c?locationLabel(c):''].filter(Boolean).join(' · '))}</p><div class="row tide-card-due">${icon(t.action)}<span>${e(t.action[0].toUpperCase()+t.action.slice(1))} · ${e(full(t.due))}${t.time?' · '+e(t.time):''}</span></div><p class="tide-card-context">${e(tideContext(t))}</p><div class="stack">${c?btn('open-contact','Open contact','secondary wide',`data-id="${e(c.id)}"`):''}${!t.completed&&!t.legacyHidden?btn('complete-tide','Complete Tide','primary wide',`data-id="${e(t.id)}"`):''}</div></div>`);}
function renderTide(id){const t=state.tides.find(t=>t.id===id);if(!t)return topbar('Tide','', '#tides')+`<div class="page">${empty('Tide not found')}</div>`;const c=contact(t.contactId);return `${topbar('Tide',btn('tide-form','Edit','outlined',`data-tide="${e(t.id)}"`),'#tides')}<div class="page tide-detail"><span class="badge tide">${icon('bell')}${e(tideGroup(t))}</span><div class="due-big">${e(short(t.due))}${t.time?` · ${e(t.time)}`:''}</div><h1>${e(t.title)}</h1><div class="panel row">${icon(t.action,'gold')}<span>${e(t.action==='other'?t.title:t.action[0].toUpperCase()+t.action.slice(1))}</span></div>${c?`<button class="panel stat-card" data-action="open-contact" data-id="${e(c.id)}">${avatar(c)}<span class="grow"><h3>${e(c.pastor)}</h3><p>${e(c.church)}</p><p>Open in ${c.wing==='manifest'?'Manifest':'Voyage'}</p></span>${icon('chevron')}</button>`:''}${t.note?`${section('Context')}<div class="panel small">${e(t.note)}</div>`:''}<div class="divider"></div>${!t.completed&&!t.legacyHidden?`<div class="stack">${btn('complete-tide',`${icon('check')}Complete Tide`,'primary wide',`data-id="${e(t.id)}"`)}${btn('reschedule','Reschedule','secondary wide',`data-id="${e(t.id)}"`)}</div>`:t.legacyHidden?`<div class="panel small">Retained legacy record—not marked completed.<p>${e(t.legacyReconciliation?.reason||"Not active in the old app")}</p></div>`:'<div class="green">Tide cleared</div>'}</div>`;}
function renderCalendar(){const counts=openCounts(state),now=new Date();return `${topbar('Open Dates',btn('today','Today','outlined'))}<div class="page"><div class="panel calendar-summary"><div><strong>${counts.sundays}</strong><span>Sundays</span></div><div><strong>${counts.wednesdays}</strong><span>Wednesdays</span></div><div class="caption">Open dates<br>Through December 31</div></div><div class="calendar-legend"><span><i style="background:#578666"></i>Meeting</span><span><i style="border:1px solid var(--gold)"></i>Open</span><span><i style="border:1px solid #b290ce"></i>Holiday</span><span><i style="background:#27b8ff"></i>Family birthday</span><span><i style="background:#a26b84"></i>Vacation</span></div>${Array.from({length:12-now.getMonth()},(_,n)=>monthGrid(new Date(now.getFullYear(),now.getMonth()+n,1,12))).join('')}</div>`;}
function monthGrid(d){const y=d.getFullYear(),m=d.getMonth(),n=new Date(y,m+1,0).getDate(),blank=d.getDay();return `<section class="calendar-month" id="month-${y}-${m}"><h2 class="month-title">${d.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div class="weekdays">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(s=>`<span>${s}</span>`).join('')}</div><div class="days">${'<span></span>'.repeat(blank)}${Array.from({length:n},(_,i)=>{const day=new Date(y,m,i+1,12),status=dayStatus(state,day),events=calendarEvents(state,day),holiday=events.some(v=>v.kind==='holiday'),birthday=events.some(v=>v.kind==='birthday'&&(v.family===true||(!v.calendarId&&!v.calendarEventId&&!v.contactId&&v.family!==false))),celebrate=events.find(v=>v.kind==='anniversary');return `<button class="day ${status} ${holiday?'holiday-tint':''} ${birthday?'birthday-tint':''} ${day.getDay()===0||day.getDay()===3?'ministry':''} ${iso(day)===iso()?'today':''}" data-action="route" data-route="#day/${iso(day)}" aria-label="${e(full(day))}, ${status}${events.length?`, ${e(events.map(v=>v.title||contact(v.contactId)?.church||v.kind).join(', '))}`:''}"><span class="day-number">${i+1}</span><span class="calendar-markers">${celebrate?icon(celebrate.kind==='birthday'?'cake':'rings','anniversary-marker'):''}</span></button>`;}).join('')}</div></section>`;}
function renderDay(id){const status=dayStatus(state,id),events=calendarEvents(state,id);return `${topbar('Open Dates','', '#calendar')}<div class="page date-detail"><div class="tiny subtle">${date(id).toLocaleDateString('en-US',{weekday:'long'}).toUpperCase()}</div><h1>${date(id).toLocaleDateString('en-US',{month:'long',day:'numeric'})}</h1><div class="date-ring">${date(id).getDate()}</div><div class="gold tiny">${status==='open'?'OPEN DATE':'UNAVAILABLE'}</div><div class="divider"></div>${events.map(v=>v.kind==='meeting'?calendarMeetingDetails(v):`<div class="panel warning"><div class="row">${icon(v.kind==='birthday'?'cake':v.kind==='anniversary'?'rings':'flag','gold')}<h3>${e(v.title)}</h3></div><p>${v.kind==='open-date'?'Yellow state marker on your calendar.':status==='protected'?'Important date—not marked available.':'Not marked available.'}</p></div>`).join('')}${status==='open'?`<div class="stack" style="margin-top:22px">${btn('meeting-form',status==='protected'?'Schedule anyway':'Schedule a meeting','primary wide',`data-date="${e(id)}" ${status==='protected'?'data-protected="true"':''}`)}${btn('route','Keep open','secondary wide','data-route="#calendar"')}</div>`:''}</div>`;}
function compassChart(pct){const p=Math.min(100,Math.max(0,pct)),r=76,length=Math.PI*r;return `<svg class="compass-chart" viewBox="0 0 240 185" aria-label="${pct}% of yearly goal received"><path d="M44 119a76 76 0 0 1 152 0" fill="none" stroke="#8baac728" stroke-width="5"/><path d="M44 119a76 76 0 0 1 152 0" fill="none" stroke="#d8ad63" stroke-width="5" stroke-dasharray="${length*p/100} ${length}"/><g stroke="#d8ad63" stroke-width="1" fill="none"><circle cx="120" cy="116" r="33"/><path d="M120 72v88M75 116h90m-45-31 9 23 22 8-22 9-9 23-9-23-23-9 23-8z"/></g><text x="116" y="65">N</text><text x="61" y="120">W</text><text x="174" y="120">E</text><text x="117" y="173">S</text></svg>`;}
function mathGrid(goal){return `<div class="math-grid"><div><strong>${MONEY.format(goal)}</strong><span>yearly</span></div><div><strong>${PRECISE.format(goal/12)}</strong><span>monthly</span></div><div><strong>${PRECISE.format(goal/52)}</strong><span>weekly</span></div></div>`;}
function renderGoal(){const s=supportStats(state,goalYear,planningOverride);const estimate=supportEstimate(state);s.annualSupport=estimate.annual;s.unknown=estimate.unknown;s.supportRemaining=Math.max(0,s.supportGoal-estimate.annual);const raisedPct=Math.round(s.annualSupport/s.goal*100);return `${topbar('Yearly giving',btn('goal-edit','Edit','plain-btn'))}<div class="page"><div class="goal-head"><h1>${MONEY.format(s.annualSupport)}</h1><p>Estimated annual support · ${MONEY.format(s.goal)} goal</p>${compassChart(raisedPct)}</div><div class="goal-progress"><div><strong class="green">${MONEY.format(Math.max(0,s.goal-s.annualSupport))}</strong><span>annual support still needed</span></div><div><strong>${raisedPct}%</strong><span>of annual support goal</span></div></div><div class="panel goal-panel row"><span class="medallion">${icon('support')}</span><div class="grow"><h3>Your support rhythm</h3><div class="amount">${PRECISE.format(s.annualSupport/52)} <span class="small subtle">/ week equivalent</span></div><div class="small subtle">${MONEY.format(estimate.confirmed)} confirmed · remaining amounts inferred from giving patterns</div></div></div><button class="panel goal-panel wide row" data-action="route" data-route="#ledger"><span class="medallion">${icon('gift')}</span><div class="grow" style="text-align:left"><h3>${goalYear} total giving received</h3><div class="amount">${MONEY.format(s.received)}</div><div class="small subtle">${s.pct}% of ${MONEY.format(s.goal)} · ${MONEY.format(s.actualRemaining)} remaining</div><p class="hint">Support ${MONEY.format(s.recurring)} + love offerings and gifts ${MONEY.format(s.gifts)}. Insurance funding ${MONEY.format(s.insurance)} also counts. Actual receipts, not added to annual support commitments.</p></div>${icon('chevron')}</button>${section('Your supporting churches')}<div class="panel goal-panel"><div class="ledger-row">Churches with recorded support<span class="amount">${estimate.churches}</span></div><div class="ledger-row">First recorded within six months<span class="amount">${estimate.newChurches}</span></div><p class="hint">First recorded gift is not a verified start date. Missing reports and incomplete history affect this count.</p><p class="small subtle">${state.calendarReview?`Calendar history: ${state.calendarReview.uniqueChurches} matched churches with past events. ${new Set(state.calendarReview.visits.filter(v=>estimate.rows.some(r=>r.church&&r.contactId===v.contactId)).map(v=>v.churchKey)).size} have recorded support (${Math.round(new Set(state.calendarReview.visits.filter(v=>estimate.rows.some(r=>r.church&&r.contactId===v.contactId)).map(v=>v.churchKey)).size/state.calendarReview.uniqueChurches*100)}%). ${state.calendarReview.unresolved.length} events need review. Snapshot through ${e(state.calendarReview.through)}; not live sync or verified attendance.`:'Churches visited and supporting percentage: unavailable until calendar history is connected and matched.'}</p></div><details class="details"><summary>How annual support is estimated</summary>${estimate.rows.map(r=>`<div class="ledger-row"><div>${e(r.label)}<p class="tiny subtle">${e(r.cadence)} · ${r.annual?e(r.basis):'More history needed'}</p></div><span>${r.annual?MONEY.format(r.annual):'Unknown'}</span></div>`).join('')}<p class="hint">Three observed months and repeated amounts are required for inferred patterns. Estimates are not promises. Faith’s insurance is excluded. Individual donors count in dollars but not church counts.</p></details>${section('Support faithfulness')}${btn('route',`${icon('support')}Review two-payment warnings`,'secondary wide','data-route="#offcourse"')}<p class="hint">Warnings are provisional until report coverage and delayed deposits are reconciled. ${s.unknown} supporters have unknown amounts or cadences.</p>${section('Plan B · Support alone')}<div class="panel goal-panel"><h3>${MONEY.format(s.annualSupport)} / ${MONEY.format(s.supportGoal)}</h3><p class="small subtle">Recorded full-year support rhythm · ${MONEY.format(s.supportRemaining)} still needed</p><p class="small subtle">${MONEY.format(s.projected)} expected for ${goalYear}, prorated for recorded start and end dates. ${s.unknown} supporters have an unknown amount or cadence.</p></div>${section('Yearly pace')}<div class="panel goal-panel"><div class="amount">${MONEY.format(Math.abs(s.paceDifference))}</div><p class="small subtle">${s.paceDifference<0?'Behind':'Ahead of'} an even yearly pace, based on recorded receipts.</p><p class="hint">Missing reports and late deposits can make this provisional. Unknown start dates are not confirmed full-year promises.</p></div>${section('Two bearings')}<div class="panel goal-panel"><h3>Starting from $0</h3>${mathGrid(s.goal)}</div><div class="panel goal-panel planning"><h3>Preaching scenario · $750 a week</h3><p class="small subtle">The additional annual income needed at this support pace. One-time gifts are not assumed.</p>${mathGrid(Math.max(0,s.goal-39000))}<p class="hint">Three churches × $250 × 52 weeks = $39,000 assumed offerings. Planning only; never counted as received. Plan B still targets $35,000 support.</p></div><div class="panel form" style="margin-top:13px"><label for="override">Try another weekly support amount</label><div class="field-row"><input id="override" type="number" min="0" step=".01" value="${planningOverride===null?'':planningOverride}" placeholder="${(s.projected/52).toFixed(2)}">${btn('use-recorded','Use recorded support','secondary')}</div><p class="hint">Temporary planning only. This never changes a church’s support record.</p></div>${section('This calendar year')}<div class="panel"><div class="ledger-row">Recurring received<span class="amount">${MONEY.format(s.recurring)}</span></div><div class="ledger-row">Love offerings<span class="amount">${MONEY.format(s.offerings)}</span></div><div class="ledger-row">Gifts / legacy combined offerings<span class="amount">${MONEY.format(s.otherGifts)}</span></div><div class="ledger-row">Sending-church insurance<span class="amount">${MONEY.format(s.insurance)}</span></div><div class="ledger-row">Total received<span class="amount green">${MONEY.format(s.received)}</span></div><div class="ledger-row">Actual remaining<span class="amount">${MONEY.format(s.actualRemaining)}</span></div></div>${section('Report coverage')}<div class="panel goal-panel"><p class="small subtle">${state.financeReview?e(state.financeReview.coverage.filter(m=>m.startsWith(String(goalYear))).join(' · ')):'Reports have not yet been reconciled in this working copy.'}</p><p class="hint">March 2026 report missing. Blank months are unknown, not zero. ${state.financeReview?`${state.financeReview.unassigned} gifts await a donor match.`:''}</p><label class="secondary wide" style="display:block;text-align:center;cursor:pointer">Import reconciled reports<input id="import-reports" type="file" accept=".json,application/json" class="sr-only"></label></div>${section('Support health')}${btn('route',`${icon('support')}Review two-payment warnings`,'secondary wide','data-route="#offcourse"')}<p class="hint">Warnings use recorded cadences, not inferred promises. Deposit delays, catch-up periods, and missing reports still need reconciliation before treating a warning as confirmed.</p>${section('Recent years')}<div class="years">${Array.from({length:4},(_,i)=>new Date().getFullYear()-i).map(y=>btn('goal-year',String(y),`chip ${goalYear===y?'active':''}`,`data-year="${y}"`)).join('')}</div><p class="tiny subtle">Each calendar year stands alone. No carryover. The goal is a single global setting.</p></div>`;}
function renderOffCourse(){const list=givingInterruptions(state);return `${topbar('Support off course')}<div class="page"><h1 class="month-title">A rhythm interrupted</h1><p class="subtle small">Flagged after two missed expected gifts. Clears automatically when giving resumes.</p>${list.map(r=>`<div class="panel" style="margin-top:13px">${directoryItem(r.contact)}<div class="small gold">${r.missed} expected gifts missed</div><div class="tiny subtle">Last support: ${r.last?short(r.last):'not yet recorded'} · ${e(r.contact.supportCadence)}</div></div>`).join('')||empty('Steady on course','Your recorded support relationships are on cadence.')}<p class="tiny subtle">A warning does not automatically create a Tide.</p></div>`;}
function renderLedger(){const records=state.gifts.filter(g=>date(g.date).getFullYear()===goalYear).sort((a,b)=>+date(b.date)-+date(a.date));return `${topbar('Giving ledger',btn('gift-form',icon('plus'),'icon-btn','aria-label="Record gift"'),'#goal')}<div class="page"><h1 class="month-title">${goalYear} received</h1><p class="hint">Reported receipts only; March estimate and undated cash are separate. Insurance and unresolved purposes are not ordinary recurring support.</p>${records.map(g=>`<div class="panel ledger-row" style="margin-top:10px">${icon('gift','gold')}<div class="grow"><div>${e(g.donor||g.church_name||contact(g.contactId)?.church||'Unmatched gift')}</div><div class="tiny subtle">${short(g.date)} · ${e(giftCategory(g)?.replace('_',' ')||'unresolved')}</div><p class="tiny subtle">${e(g.reportMemo||g.memo||'')}<br>${e(g.reportSource||g.source||'')} · row ${e(g.reportRow||g.row||'Unknown')}</p></div><span class="amount">${MONEY.format(g.amount)}</span></div>`).join('')||empty('No gifts recorded','This year starts from zero.')}</div>`;}
function renderSettings(){
 prepareSheetsSignIn().catch(()=>{});
 const family=state.events.filter(v=>v.kind==='birthday'||v.kind==='anniversary');
 return `${topbar('Settings')}<div class="page">${section('Preferences')}<label class="settings-row"><div class="grow"><h3>Show contacts without numbers</h3><p>Apply in Manifest, Voyage, and calling courses.</p></div><input class="toggle" id="show-no-numbers" type="checkbox" ${state.settings.showNoNumbers?'checked':''}></label><div class="settings-row"><div class="grow"><h3>Annual support goal</h3><p>${MONEY.format(state.settings.yearlyGoal)}</p></div>${btn('goal-edit','Edit','plain-btn')}</div><div class="settings-row"><div class="grow"><h3>Relay rhythm</h3><p>Groups 1–4 follow the Mondays of each month.</p></div>${icon('helm','gold')}</div>${section('Family dates')}${family.map(v=>`<div class="settings-row">${icon(v.kind==='birthday'?'cake':'rings','gold')}<span class="grow">${e(v.title)}<br><span class="tiny subtle">${short(v.date)} · Annual</span></span></div>`).join('')}${btn('family-form',`${icon('plus')}Add celebration`,'secondary wide')}<div id="advanced-imported">${state.importReview?`${section('Imported history')}${btn('route','Review unmatched records','secondary wide','data-route="#importreview"')}`:''}</div><div id="advanced-backup">${section('Backup')}<div class="stack">${btn('export',`${icon('download')}Export working copy`,'secondary wide')}</div></div><details class="details" id="advanced-tools"><summary>Advanced tools</summary>${btn('recipient-update','Import confirmed recipients','secondary wide')}${renderSheetsSettings()}${section('Email history')}${btn('route','Email matching & review','secondary wide','data-route="#emailhistory"')}${section('Restore or migrate')}<div class="stack"><label class="secondary wide" style="text-align:center;cursor:pointer">Import a Relay backup<input id="import-backup" type="file" accept="application/json,.json" class="sr-only"></label>${btn('connect','Read old app records','secondary wide')}</div></details></div>`;
}
function optionsContacts(selected){return state.contacts.filter(c=>!c.archived).sort((a,b)=>a.pastor.localeCompare(b.pastor)).map(c=>`<option value="${e(c.id)}" ${c.id===selected?'selected':''}>${e(c.pastor)} · ${e(c.church)} (${c.wing})</option>`).join('');}
function plotCourse(){openSheet('Plot a course',`<form id="plot-course" class="form"><p class="small subtle">Start around a church or a city. Your course stays until you complete it.</p><label for="course-anchor-search">Church at the center</label><input id="course-anchor-search" type="search" placeholder="Search church, pastor, city or state…" autocomplete="off" value="${e(contact(state.course?.anchorId)?.church||'')}" aria-controls="course-anchor-results"><input type="hidden" name="anchor" value="${e(state.course?.anchorId||'')}"><div id="course-anchor-selected" class="hint">${contact(state.course?.anchorId)?e(contact(state.course.anchorId).pastor+' · '+locationLabel(contact(state.course.anchorId))):'Search and choose a church below.'}</div><div id="course-anchor-results" class="anchor-results" aria-live="polite"></div><label>Or city and state<input name="city" placeholder="Kankakee, IL" autocomplete="off"></label><p class="hint">Enter a city to use its center instead of a church. City lookup needs internet.</p><label>Radius in miles<input name="radius" type="number" min="1" max="1500" value="${state.course?.radius||50}" required></label><div class="submit-row"><button class="primary" type="submit">Open course list</button></div><p class="hint">Contacts need saved map coordinates for proximity search. People without a usable number stay hidden.</p></form>`);}
function editContact(id){const c=contact(id)||{wing:wing==='manifest'?'manifest':'voyage',phone:[],email:[],lodging:'Unknown',rv:'Unknown',handouts:'Unknown'};openSheet(id?'Edit contact':'Add contact',`<form id="edit-contact" data-id="${e(id||'')}" class="form"><label>Contact photo<input name="photoFile" type="file" accept="image/jpeg,image/png,image/webp"></label>${c.photo?`<label class="check"><input name="removePhoto" type="checkbox">Remove current photo</label>`:''}<p class="hint">Photos are resized and saved in this browser’s working copy and backups.</p><label>Contact designation<select name="contactType">${CONTACT_TYPES.map(type=>`<option ${type===(c.contactType||'Pastor / church')?'selected':''}>${e(type)}</option>`).join('')}</select></label><label class="check"><input name="emailList" type="checkbox" ${c.emailList===true?'checked':''}>Receives ministry emails</label><label>Name<input name="pastor" value="${e(c.pastor||'')}" required></label><label>Church<input name="church" value="${e(c.church||'')}"></label><div class="field-row"><label>City<input name="city" value="${e(c.city||'')}"></label><label>State<select name="state"><option value="">Not set</option>${STATES.map(s=>`<option ${c.state===s?'selected':''}>${s}</option>`).join('')}</select></label></div><input type="hidden" name="wing" value="${c.wing}"><label>Phone numbers · one per line<textarea name="phone">${e(phones(c).join('\n'))}</textarea></label><label>Email addresses · one per line<textarea name="email">${e(emails(c).join('\n'))}</textarea></label><label>Street address<input name="address" value="${e(c.address||'')}"></label><div class="field-row"><label>Latitude<input name="lat" type="number" step="any" min="-90" max="90" value="${e(c.lat??'')}"></label><label>Longitude<input name="lng" type="number" step="any" min="-180" max="180" value="${e(c.lng??'')}"></label></div>${c.wing==='manifest'?`<label>Support status<select name="supportStatus">${['Supporting','Non-supporting'].map(v=>`<option ${c.supportStatus===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="field-row"><label>Support amount<input name="supportAmount" min="0" type="number" step=".01" value="${e(c.supportAmount||'')}"></label><label>Cadence<select name="supportCadence"><option value="">Not set</option>${['Weekly','Bi-weekly','Monthly','Bi-monthly','Quarterly','Bi-annual','Annually','Irregular'].map(v=>`<option ${c.supportCadence===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="field-row"><label>Change effective date<input name="supportEffective" type="date" value="${iso()}" required></label><label>Support starts<input name="supportStart" type="date" value="${e(c.supportStart||'')}"></label><label>Support ends<input name="supportEnd" type="date" value="${e(c.supportEnd||'')}"></label></div>${[['Lodging','lodging'],['RV hookup','rv'],['Bible handouts','handouts']].map(([n,k])=>`<label>${n}<select name="${k}">${['Unknown','Available','Unavailable'].map(v=>`<option ${c[k]===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}`:''}<label>Notes<textarea name="notes">${e(c.notes||'')}</textarea></label><div class="submit-row"><button class="primary" type="submit">Save contact</button></div></form>`);}
function launchContactAction(id,kind){const c=contact(id);if(!c)return;const values=kind==='email'?emails(c):phones(c),prefix=kind==='call'?'tel:':kind==='text'?'sms:':'mailto:';if(values.length===1){location.href=prefix+(kind==='email'?values[0]:values[0].replace(/[^+\d]/g,''));return;}if(!values.length){toast(`No ${kind==='email'?'email address':'phone number'} recorded.`);return;}openSheet(`${kind[0].toUpperCase()+kind.slice(1)} ${c.pastor}`,`<div class="contact-menu">${values.map(v=>`<a href="${prefix}${e(kind==='email'?v:v.replace(/[^+\d]/g,''))}">${icon(kind)}${e(v)}</a>`).join('')}</div>`);}
