document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message));if(el.dataset.action==='route'&&sheet.open)closeSheet();});
document.addEventListener('submit',event=>{if(event.target.id==='weekly-message'){event.preventDefault();state.settings.weeklyRelayMessage=new FormData(event.target).get('message');save('Weekly message saved');render();return;}if(!event.target.closest('#sheet'))return;event.preventDefault();submit(event.target).catch(err=>toast(err.message));});
document.addEventListener('input',event=>{if(event.target.id==='directory-search'){searchText=event.target.value;const results=document.querySelector('#directory-results');if(results)results.innerHTML=wing==='voyage'?voyageDirectory():filteredDirectory(wing).map(c=>directoryItem(c)).join('')||empty('No matches');else if(wing==='tides'){const caret=event.target.selectionStart;render();const input=document.querySelector('#directory-search');input.focus();input.setSelectionRange(caret,caret);}}});
document.addEventListener('change',async event=>{
	 const el=event.target;
	 if(el.id==='directory-filter-select'){directoryFilter=el.value;render();return;}
 if(el.id==='import-email-history'&&el.files?.[0]){try{const next=importEmailHistory(state,JSON.parse(await el.files[0].text()));if(confirm('Import email metadata into this working copy? Gmail itself will not be changed.')){state=next;if(await save('Email history imported'))go('#emailhistory');}}catch(error){toast(error.message);}el.value='';return;}
 if(el.id==='import-device-activity'&&el.files?.[0]){try{const result=importDeviceActivity(state,JSON.parse(await el.files[0].text()));if(await save(`${result.added} call/text records matched`))render();}catch(error){toast(error.message);}el.value='';return;}
 if(el.id==='import-calendar-metadata'&&el.files?.[0]){try{const next=importCalendarMetadata(state,JSON.parse(await el.files[0].text()));const summary=next.calendarSync.summary;if(confirm(`Apply this Calendar update? ${summary.added} added, ${summary.updated} updated, ${summary.cancelled} cancelled, and ${summary.unmatched} need matching. Relay journals and notes will be kept.`)){state=next;if(await save('Calendar metadata updated'))render();}}catch(error){toast(error.message);}el.value='';return;}
 if(el.id==='import-reports'&&el.files?.[0]){try{const bundle=JSON.parse(await el.files[0].text());const next=mergeGivingReports(state,bundle);if(confirm(`Add ${next.financeReview.added} new gifts and reconcile ${next.financeReview.matched} existing entries? No contacts or conversations will be replaced.`)){state=next;if(await save('Reports reconciled · existing records preserved'))go('#goal');}}catch(err){toast(err.message);}el.value='';}
 if(el.id==='show-no-numbers'){state.settings.showNoNumbers=el.checked;save('Contact visibility updated');}
 if(el.id==='course-type'||el.id==='course-result'){state.course[el.id==='course-type'?'type':'result']=el.value;save('');render();}
 if(el.id==='log-type'){sheet.querySelector('#log-results').innerHTML=outcomes(el.value);}
 if(el.id==='override'){planningOverride=el.value===''?null:Number(el.value);render();}
 if(el.id==='reconcile-tides'&&el.files?.[0]){try{const next=reconcileTides(state,JSON.parse(await el.files[0].text()));const blob=new Blob([exportData(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='relay-before-tide-reconciliation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state=reconcileContactDesignations(next);save('Tides reconciled; original records retained');render();}catch(err){toast(err.message);}return;}
 if(el.id==='import-backup'&&el.files?.[0]){try{const next=parseImport(await el.files[0].text());if(confirm('Replace this working copy with the backup?')){state=next;if(!await save('Backup restored'))return;go('#helm');}}catch(err){toast(err.message);}}
});
window.addEventListener('hashchange',()=>{closeSheet();window.scrollTo(0,0);render();});
window.addEventListener('offline',()=>toast('Offline · your working copy remains available'));
document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(state.course?.mode==='state'&&state.course.selectedDate!==iso()){state.course=null;save('');}render();}});
if(state.course?.mode==='state'&&state.course.selectedDate!==iso()){state.course=null;save('');}
render();
async function startPrivateSync(){
 try{
  await prepareDriveSignIn();
  if(!driveAuthorized()&&state.cloudSync&&!privateHostActive())await authorizeDrive({silent:true});
  if(driveAuthorized())await autoSync(!state.contacts.length);
 }catch{/* Google may require one visible Connect tap after the browser fully closes. */}
 finally{showStartupPrompts();}
}
function showStartupPrompts(){
 if(sheet.open||showMeetingReminder())return;
 const donorEmailReminders=missingDonorEmails(state.contacts);
 if(donorEmailReminders.length)openSheet('Add supporting donors’ emails',`<p class="small subtle">These supporting individuals still need email addresses for your email list. Tap a name to edit their details.</p><div class="stack">${donorEmailReminders.map(c=>btn('donor-email-edit',e(c.pastor||c.givingDonorLabel),'secondary wide donor-email-reminder',`data-id="${e(c.id)}" aria-label="Add email for ${e(c.pastor||c.givingDonorLabel)}"`)).join('')}</div><p class="hint">This reminder returns when you open the app until all four have email addresses.</p>${btn('close-sheet','Later','secondary wide')}`);
}
startPrivateSync();
if(startupSaveFailed)toast('Browser storage is full. Your saved copy is intact; export a backup before editing.');
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
